--
-- Table structure for table `compounds`
--

DROP TABLE IF EXISTS `compounds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `compounds` (
  `compound_id` bigint NOT NULL AUTO_INCREMENT COMMENT '化合物ID',
  `target_category` varchar(100) NOT NULL COMMENT '目标类别',
  `substance_category` varchar(100) NOT NULL COMMENT '目标物质类别',
  `substance_subclass` varchar(100) DEFAULT NULL COMMENT '目标物质子类',
  `drug_name` varchar(300) NOT NULL,
  `indications` longtext,
  `prescription_type` enum('处方药','非处方药','其他') DEFAULT NULL COMMENT '处方/非处方',
  `biomarker_name` varchar(300) DEFAULT NULL,
  `biomarker_cas` varchar(50) DEFAULT NULL COMMENT '生物标记物CAS',
  `physicochemical_properties` longtext,
  `calibration_coefficient` decimal(15,6) DEFAULT NULL COMMENT '校准系数',
  `human_excretion_rate` decimal(8,4) DEFAULT NULL COMMENT '人体排泄率(%)',
  `consumption_value` decimal(20,4) DEFAULT NULL COMMENT '药物消费量_value',
  `consumption_unit` varchar(30) DEFAULT NULL COMMENT '药物消费量_unit',
  `usage_prevalence` decimal(8,4) DEFAULT NULL COMMENT '药物使用流行率(%)',
  `disease_prevalence` decimal(8,4) DEFAULT NULL COMMENT '疾病患病率(%)',
  `keywords` longtext,
  `doi` varchar(200) DEFAULT NULL,
  `abstract` longtext,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`compound_id`),
  UNIQUE KEY `uk_drug_name` (`drug_name`,`biomarker_cas`)
) ENGINE=InnoDB AUTO_INCREMENT=574 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='化合物/药物信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `compounds`
--

LOCK TABLES `compounds` WRITE;
/*!40000 ALTER TABLE `compounds` DISABLE KEYS */;
INSERT INTO `compounds` VALUES (1,'药物类','抗生素','林可酰胺类','克林霉素','抗感染','处方药','克林霉素','18323-44-9',NULL,9.070000,10.0000,34.0000,'mg/day/1000 inh',NULL,NULL,'Public health; Sewage surveillance; Chemical biomarkers; Pharmaceuticals; Chronic disease burden','10.1016/j.watres.2026.125632','Wastewater-based epidemiology (WBE) can provide a multidimensional health check-up for community-wide health. We conducted a city sewage health scan in Hong Kong by analyzing 401 time-proportional composite samples from 12 sewersheds over five weeks, classifying 117 biomarkers, referencing the local drug formulary and WHO ICD-11, into 45 features and seven health categories (infectious, endocrine, central nervous system, cardiovascular, respiratory, pain-related, and lifestyle). Our findings contextualized Hong Kong\'s longevity, showing that Hong Kong\'s biomarker levels are moderate globally, but with a relatively high burden of chronic disease and respiratory medications. Respiratory medication use was more strongly linked to ambient air qualityespecially traffic-related CO-than to nicotine exposure, underscoring environmental factors associated with the respiratory burden. This multidimensional approach enables systematic mapping of health burdens and needs at intra-city level as well, highlighting the value of WBE for targeted public health monitoring. Furthermore, by comparing WBE-based estimates with traditional survey data, we demonstrate that WBE captures communitylevel pharmacotherapy for chronic conditions and reveals underreported antibiotic and tobacco use, supporting improved public health surveillance.','2026-06-15 20:40:21','2026-06-15 20:40:21'),(2,'药物类','抗生素','林可酰胺类','林可霉素','抗感染','处方药','林可霉素','154-21-2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Public health; Sewage surveillance; Chemical biomarkers; Pharmaceuticals; Chronic disease burden','10.1016/j.watres.2026.125632','Wastewater-based epidemiology (WBE) can provide a multidimensional health check-up for community-wide health. We conducted a city sewage health scan in Hong Kong by analyzing 401 time-proportional composite samples from 12 sewersheds over five weeks, classifying 117 biomarkers, referencing the local drug formulary and WHO ICD-11, into 45 features and seven health categories (infectious, endocrine, central nervous system, cardiovascular, respiratory, pain-related, and lifestyle). Our findings contextualized Hong Kong\'s longevity, showing that Hong Kong\'s biomarker levels are moderate globally, but with a relatively high burden of chronic disease and respiratory medications. Respiratory medication use was more strongly linked to ambient air qualityespecially traffic-related CO-than to nicotine exposure, underscoring environmental factors associated with the respiratory burden. This multidimensional approach enables systematic mapping of health burdens and needs at intra-city level as well, highlighting the value of WBE for targeted public health monitoring. Furthermore, by comparing WBE-based estimates with traditional survey data, we demonstrate that WBE captures communitylevel pharmacotherapy for chronic conditions and reveals underreported antibiotic and tobacco use, supporting improved public health surveillance.','2026-06-15 20:40:21','2026-06-15 20:40:21'),(3,'药物类','抗生素','大环内酯类','阿奇霉素','抗感染','处方药','阿奇霉素','83905-01-5',NULL,1.800000,NULL,189.0000,'mg/day/1000 inh',NULL,NULL,'Public health; Sewage surveillance; Chemical biomarkers; Pharmaceuticals; Chronic disease burden','10.1016/j.watres.2026.125632','Wastewater-based epidemiology (WBE) can provide a multidimensional health check-up for community-wide health. We conducted a city sewage health scan in Hong Kong by analyzing 401 time-proportional composite samples from 12 sewersheds over five weeks, classifying 117 biomarkers, referencing the local drug formulary and WHO ICD-11, into 45 features and seven health categories (infectious, endocrine, central nervous system, cardiovascular, respiratory, pain-related, and l