  `plant_id` bigint NOT NULL AUTO_INCREMENT,
  `plant_name` varchar(200) NOT NULL COMMENT '污水厂名称',
  `treatment_capacity_m3_day` bigint DEFAULT NULL COMMENT '处理规模(m3/day)',
